void BPHttpMessage::Parse(std::vector lines) {
 std::smatch match;
 std::string pattern\_req = "(POST|GET|PUT|HEAD|DELETE|CONNECT|OPTIONS|TRACE)\\s+([a-zA-Z\\/.-]+)\\s+([a-zA-Z]+)\\/([0-9.]+)\r\*$";
 std::string pattern\_resp = "HTTP\\/([0-9.]+)\\s+([0-9]+)\\s+(.\*)";
 std::string pattern\_header = "^([a-zA-Z-]+):\\s+(.\*)\r\*\n\*";

 std::regex regex\_req(pattern\_req);
 std::regex regex\_resp(pattern\_resp);
 std::regex regex\_header(pattern\_header); 

 for (std::vector::iterator it = lines.begin(); it != lines.end(); it++) {

 if (std::regex\_match(\*it, match, regex\_req)) {
 this->msg\_type = "request";
 this->entity\_head = \*it;
 } else if (std::regex\_match(\*it, match, regex\_resp )) {
 this->msg\_type = "response";
 this->entity\_head = \*it;
 } else if (std::regex\_match(\*it, match, regex\_header)) {
 this->header\_map[match[1]] = match[2];
 } else if (\*it =="\r\n") {
 it++;
 while (it != lines.end()){
 this->body += \*it;
 it++;
 }
 break;
 }
 }
}
