// \*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\* fonction de détection de flanc montant
bool fm(bool etat, bool \*etatprec)
{
 if( etat == true && \*etatprec == false)
 {
 \*etatprec = true;
 return true;
 }
 else if (etat == false && \*etatprec == true)
 {
 \*etatprec = false;
 return true;
 }
 else
 return false;
}
// \*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\* fonction de détection de flanc descendant
bool fd(bool etat, bool \*etatprecfd)
{

 if (etat == false && \*etatprecfd == true)
 {
 \*etatprecfd = false;
 return true;
 }
 if( etat == true && \*etatprecfd == false)
 {
 \*etatprecfd = true;
 }
 return false;
}

// \*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\* fonction de comptage de flanc montant
int comptfm(bool fm, int compteur)
{
 if(fm == true)
 {
 return (compteur + 1) ; 
 }
 return compteur;
}

